    vector<vector<double>> keys={{1,0},{0,1}};
    vector<double> values={2,5};
    vector<double> score;
    for(const auto& key:keys){
        double dot=0;
        for(int i=0;i<int(query.size());i++)dot+=query[i]*key[i];
        score.push_back(dot/sqrt(double(query.size())));
    }
    double largest=*max_element(score.begin(),score.end());
    double total=0;
    for(double& s:score){s=exp(s-largest);total+=s;}
    double output=0;
    for(int i=0;i<int(score.size());i++)output+=score[i]/total*values[i];
    cout<<fixed<<setprecision(6)<<output<<"\n";
    return 0;
}

